from PySide6.QtGui import QGuiApplication, QIcon, QImage, QMouseEvent, QPainter, QPixmap
from PySide6.QtCore import QSize, Qt, Signal
from PySide6.QtWidgets import QAbstractButton, QApplication, QLabel

from anaouder.utils import get_resource_path



